function pipeUnder(x,y){const row=level.tiles[y+1];if(!row||row[x]!=='pipe'||level.tiles[y][x]==='pipe')return null;let s=x;while(s>0&&row[s-1]==='pipe')s--;const left=s+2*Math.floor((x-s)/2);return {x:left,w:row[left+1]==='pipe'?2:1}}
